    TUSDC.approve(address(market), type(uint256).max);

    uint256 aliceOffer = market.offer(12 ether, ERC20(TEST), 50 * 1e6, ERC20(TUSDC), address(alice), address(alice));
    vm.expectRevert("can't hide");
    market.cancel(aliceOffer);

  vm.stopPrank();

}
```

